/// <summary>
/// Handle the search functions see app.config "ISearchService"
/// </summary>
[TFMDocumentType(staticMethodStr(TFMConstants, Search))]
public class TFMSearchService extends TFMDocumentHandler
{
    Set             idUsed;
}

Method.Source:
public void process()
{
    TFMRequestSearchElement searchRequest = request;
    TFMOrderTypes           type = searchRequest.parmType();
    TFMSearchHandler        result = TFMSearchHandler::getSearchHandlerFromType(searchRequest);
    if (result != null)
    {            
        result.performSearch();
        responseElement = result.getResponse();
    }
    else
    {
        this.doSearch(type); // For Backwards Compatibility
    }
}

[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration LocalItemSearch()
{
    TFMRegistrationCollectorText itemNumber;
    TFMRegistrationCollectorText itemBarcode;
    TFMRegistrationCollectorText lotNumber;
    TFMRegistrationCollectorText serial;
    TFMRegistrationCollectorText description;
    TFMReferenceDataConfiguration ret = new TFMReferenceDataConfiguration();

    description = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(Description));
    ret.addCollector(description);

    itemNumber = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(ItemId));
    itemNumber.parmName(TFMConstants::ItemNumber());
    ret.addCollector(itemNumber);

    itemBarcode = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(ItemBarcode));
    ret.addCollector(itemBarcode);

    lotNumber = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(InventBatchId));
    lotNumber.parmName(TFMConstants::LotNumber());
    ret.addCollector(lotNumber);

    serial = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(InventSerialId));
    serial.parmName(TFMConstants::SerialNumber());
    ret.addCollector(serial);
    ret.parmAlwaysIncludeInOutput(true);
    return ret;
}

/// <summary>
/// Method to get the content subject
/// </summary>
/// <returns>Returns the content subject.</returns>
public TFMDocumentContentSubject getDocumentContentSubject()
{

    TFMRequestSearchElement searchRequest = request;
    TFMDocumentContentSubject type = searchRequest.parmType();
    TFMDocumentContentSubject subject = type;

    return subject;
}

